#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = numeric_limits<ll>::max() / 2;

struct Edge {
    int v;
    ll w;
};

vector<vector<Edge>> adj;

vector<ll> dijkstra(int start, int n) {
    vector<ll> dist(n + 1, INF);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    pq.push({0, start});
    dist[start] = 0;
    while (!pq.empty()) {
        ll d = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (d > dist[u]) continue;
        for (const auto& e : adj[u]) {
            int v = e.v;
            ll w = e.w;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m, k;
    cin >> n >> m >> k;
    adj.resize(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        ll w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }
    vector<ll> d1 = dijkstra(1, n);
    vector<ll> dn = dijkstra(n, n);
    vector<pair<ll, ll>> valid_nodes;
    for (int v = 1; v <= n; ++v) {
        if (d1[v] < INF && dn[v] < INF) {
            valid_nodes.push_back({d1[v], dn[v]});
        }
    }
    for (int i = 0; i < k; ++i) {
        ll a, b;
        cin >> a >> b;
        ll min_wait = INF;
        for (const auto& node : valid_nodes) {
            ll t1 = a * node.first;
            ll t2 = b * node.second;
            ll diff = abs(t1 - t2);
            if (diff < min_wait) {
                min_wait = diff;
            }
        }
        cout << min_wait << "\n";
    }
    return 0;
}
