  const [currentPath, setCurrentPath] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const batchSize = 10;
  const padding = 40;

  // Ref to hold canvas context
  const canvasRef = useRef({
    points: [],
    currentBatch: 0,
    lines: [],
    currentPath: [],
  });

  // Coordinate scaling
  const scalePoint = (point) => {
    return {
      x: (point.x / 2160) * (width - 2 * padding) + padding,
      y: (point.y / 2160) * (height - 2 * padding) + padding,
    };
  };

  // Update canvas ref when state changes
  useEffect(() => {
    canvasRef.current = {
      ...canvasRef.current,
      points,
      currentBatch,
      lines,
      currentPath,
    };
  }, [points, currentBatch, lines, currentPath]);

  // Fetch points from API
  useEffect(() => {
    const loadPoints = async () => {
      try {
        const data = await fetchPoints();
        setPoints(data);
        canvasRef.current.points = data;
        setLoading(false);
      } catch (err) {
        setError('Failed to load points');
        Alert.alert(
          'Error',
          'Failed to load points. Please check your connection.',
          [{ text: 'OK' }]
        );
        setLoading(false);
      }
    };

    loadPoints();
  }, []);

  // Find closest point to touch
  const findClosestPoint = (x, y) => {
    const startIdx = currentBatch * batchSize;
    const endIdx = Math.min(startIdx + batchSize, points.length);
    let closest = null;
    let minDist = 2500; // 50px radius threshold

    for (let i = startIdx; i < endIdx; i++) {
      const scaled = scalePoint(points[i]);
      const dx = scaled.x - x;
      const dy = scaled.y - y;
      const dist = dx * dx + dy * dy;

      if (dist < minDist) {
        minDist = dist;
        closest = scaled;
      }
    }

    return minDist < 2500 ? closest : null;
  };

  // Touch handling
  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt, gestureState) => {
        const touchX = gestureState.x;
        const touchY = gestureState.y;
        const closest = findClosestPoint(touchX, touchY);

        if (closest) {
          setCurrentPath([closest.x, closest.y]);
        }
      },
      onPanResponderMove: (evt, gestureState) => {
        if (currentPath.length === 0) return;

        setCurrentPath(prev => [...prev, gestureState.x, gestureState.y]);
      },
      onPanResponderRelease: () => {
        if (currentPath.length > 0) {
          setLines(prev => [...prev, { points: [...currentPath] }]);
          setCurrentPath([]);
        }

        const nextBatchStart = (currentBatch + 1) * batchSize;
        if (nextBatchStart < points.length) {
          setCurrentBatch(prev => prev + 1);
        }
      },
    })
  ).current;

  // Render function with batch management
  if (loading) {
    return <Text style={styles.loading}>Loading points...</Text>;
  }

  if (error) {
    return <Text style={styles.error}>{error}</Text>;
  }

  const startIdx = currentBatch * batchSize;
  const currentPoints = points
    .slice(startIdx, startIdx + batchSize)
    .map(p => scalePoint(p));

  return (
    <View style={styles.container} {...panResponder.props}>
      <Svg style={styles.svg}>
        {/* Existing lines */}
        {lines.map((line, index) => (
          <Path
            key={`line-${index}`}
            d={`M ${line.points.join(' ')}`}
            stroke="blue"
            strokeWidth="2"
            fill="none"
          />
        ))}

        {/* Current path */}
        {currentPath.length > 0 && (
          <Path
            d={`M ${currentPath.join(' ')}`}
            stroke="blue"
            strokeWidth="2"
            fill="none"
          />
        )}

        {/* Current batch points */}
        {currentPoints.map((point, index) => (
          <Circle
            key={`point-${startIdx + index}`}
            cx={point.x}
            cy={point.y}
            r={10}
            fill="red"
          />
        ))}

        {/* Point labels */}
        {currentPoints.map((point, index) => (
          <SvgText
            key={`label-${startIdx + index}`}
            x={point.x + 5}
            y={point.y + 5}
            fontSize="14"
            fill="black"
          >
            {startIdx + index + 1}
          </SvgText>
        ))}
      </Svg>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'white',
  },
  svg: {
    flex: 1,
  },
  loading: {
    flex: 1,
    textAlign: 'center',
    marginTop: 50,
  },
  error: {
    color: 'red',
    textAlign: 'center',
    margin: 20,
  },
});

