const nodemailer = require('nodemailer');
const Queue = require('bull');

const app = express();
const upload = multer({ dest: 'uploads/' });

// Configure Bull queue
const customerImportQueue = new Queue('customer import', 'redis://127.0.0.1:6379');

// Configure PostgreSQL connection pool
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

// Configure email transporter
const transporter = nodemailer.createTransport({
  host: 'smtp.example.com',
  auth: {
    user: process.env.SMTP_USER,
    pass: process.env.SMTP_PASS
  }
});

// Email notification function
const sendNotification = async (success, error = null) => {
  const message = {
    from: 'no-reply@company.com',
    to: success ? process.env.ADMIN_EMAIL : error.email,
    subject: success ? 'Import Success' : 'Import Failed',
    text: success 
      ? 'Customer data has been successfully imported' 
      : `Import error: ${error.message}`
  };

  try {
    await transporter.sendMail(message);
  } catch (err) {
    console.error('Email notification failed:', err);
  }
};

// Process CSV job function
const processCSVJob = async (job) => {
  const { filePath, adminEmail } = job.data;
  const batchSize = 500;
  let batch = [];

  try {
    const client = await pool.connect();

    // Read CSV file
    const file = await fsPromises.readFile(filePath, 'utf8');

    // Parse CSV
    parse(file, {
      header: true,
      step: async (results) => {
        batch.push(results.data[0]);

        if (batch.length >= batchSize) {
          await insertBatch(client, batch);
          batch = [];
        }
      },
      complete: async () => {
        if (batch.length > 0) {
          await insertBatch(client, batch);
        }

        await client.release();
        await fsPromises.unlink(filePath);
        await sendNotification(true);
      },
      error: async (err) => {
        await client.release();
        await fsPromises.unlink(filePath);
        await sendNotification(false, { message: err.message, email: adminEmail });
      }
    });
  } catch (err) {
    await sendNotification(false, { message: err.message, email: adminEmail });
    throw err;
  }
};

// Batch insert function
const insertBatch = async (client, batch) => {
  if (batch.length === 0) return;

  const columns = Object.keys(batch[0]).join(', ');
  const values = batch.map((row, i) => 
    `(${Object.keys(batch[0]).map((_, j) => 
      `$${i * Object.keys(row).length + j + 1}`
    ).join(', ')})`
  ).join(', ');

  const flatValues = batch.flatMap(Object.values);

  try {
    await client.query(`INSERT INTO customers (${columns}) VALUES ${values}`, flatValues);
  } catch (err) {
    throw err;
  }
};

// Add job to queue
const addJobToQueue = (filePath, adminEmail) => {
  return customerImportQueue.add({
    filePath,
    adminEmail
  }, {
    attempts: 3,
    backoff: {
      type: 'exponential',
      delay: 5000
    }
  });
};

// Process queue
customerImportQueue.process(processCSVJob);

// API endpoint
