    res.status(202).json({
      status: 'Import started in background',
      fileId: req.file.filename
    });
  } catch (err) {
    console.error('Failed to start import:', err);
    res.status(500).json({
      error: 'Failed to start import'
    });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));
