#include <windows.h>
#include <winhttp.h>
#include <iostream>

#pragma comment(lib, "winhttp.lib")

void TorHttpRequest(const std::wstring& hostname) {
    HINTERNET hSession = WinHttpOpen(L"WinHTTP Example/1.0",  
                                     WINHTTP_ACCESS_TYPE_PROXY,  
                                     L"127.0.0.1:9050",  // Tor SOCKS proxy
                                     WINHTTP_NO_PROXY_BYPASS, 0);  

    if (!hSession) {
        std::cerr << "WinHttpOpen failed: " << GetLastError() << "\n";
        return;
    }

    // Configure proxy type
    WINHTTP_PROXY_INFO proxyInfo;
    proxyInfo.dwAccessType = WINHTTP_PROXY_TYPE_SOCKS;
    proxyInfo.lpszProxy = L"127.0.0.1:9050";
    proxyInfo.lpszProxyBypass = WINHTTP_NO_PROXY_BYPASS;

    if (!WinHttpSetOption(hSession, WINHTTP_OPTION_PROXY, &proxyInfo, sizeof(proxyInfo))) {
        std::cerr << "WinHttpSetOption failed: " << GetLastError() << "\n";
        WinHttpCloseHandle(hSession);
        return;
    }

    // Connect to hidden service
    HINTERNET hConnect = WinHttpConnect(hSession, hostname.c_str(),  
                                        INTERNET_DEFAULT_HTTPS_PORT, 0);

    if (!hConnect) {
        std::cerr << "WinHttpConnect failed: " << GetLastError() << "\n";
        WinHttpCloseHandle(hSession);
        return;
    }

    // Create request handle
    HINTERNET hRequest = WinHttpOpenRequest(hConnect, L"GET", NULL,  
                                            WINHTTP_NO_REFERER,  
                                            WINHTTP_DEFAULT_ACCEPT_TYPES,  
                                            WINHTTP_FLAG_SECURE);  // HTTPS

    if (!hRequest) {
        std::cerr << "WinHttpOpenRequest failed: " << GetLastError() << "\n";
        WinHttpCloseHandle(hConnect);
        WinHttpCloseHandle(hSession);
        return;
    }

    // Send request
    if (!WinHttpSendRequest(hRequest, WINHTTP_NO_ADDITIONAL_HEADERS, 0,  
                            WINHTTP_NO_REQUEST_DATA, 0, 0, 0)) {
        std::cerr << "WinHttpSendRequest failed: " << GetLastError() << "\n";
        WinHttpCloseHandle(hRequest);
        WinHttpCloseHandle(hConnect);
        WinHttpCloseHandle(hSession);
        return;
    }

    // End request
    if (!WinHttpReceiveResponse(hRequest, NULL)) {
        std::cerr << "WinHttpReceiveResponse failed: " << GetLastError() << "\n";
        WinHttpCloseHandle(hRequest);
        WinHttpCloseHandle(hConnect);
        WinHttpCloseHandle(hSession);
        return;
    }

    // Read response
    DWORD dwSize = 0;
    DWORD dwDownloaded = 0;
    LPSTR pszOutBuffer;

    do {
        if (!WinHttpQueryDataAvailable(hRequest, &dwSize)) {
            std::cerr << "WinHttpQueryDataAvailable failed: " << GetLastError() << "\n";
            break;
        }

        pszOutBuffer = new char[dwSize + 1];
        if (!pszOutBuffer) {
            std::cerr << "Out of memory\n";
            break;
        }

        ZeroMemory(pszOutBuffer, dwSize + 1);

        if (!WinHttpReadData(hRequest, (LPVOID)pszOutBuffer, dwSize, &dwDownloaded)) {
            std::cerr << "WinHttpReadData failed: " << GetLastError() << "\n";
        } else {
            std::wcout << L"Response: " << pszOutBuffer << "\n";
        }

        delete[] pszOutBuffer;
    } while (dwSize > 0);

    // Clean up
    WinHttpCloseHandle(hRequest);
    WinHttpCloseHandle(hConnect);
    WinHttpCloseHandle(hSession);
}

int main() {
    // Hidden service must be running and Tor configured with:
    // SOCKSPort 9050
    // DNSPort 0
    TorHttpRequest(L"exampleonionaddress.onion");
    return 0;
}
