    /// <summary>
    /// Provides extension methods for working with McTable in Multicad .NET API.
    /// </summary>
    public static class TableExtensions
    {
        /// <summary>
        /// Embeds geometric primitives into a specified cell of an McTable.
        /// </summary>
        /// <param name="table">The target McTable object.</param>
        /// <param name="rowIndex">Zero-based index of the target row.</param>
        /// <param name="columnIndex">Zero-based index of the target column.</param>
        /// <param name="entities">List of EntityGeometry objects to embed.</param>
        /// <exception cref="ArgumentNullException">Thrown if table or entities is null.</exception>
        /// <exception cref="ArgumentOutOfRangeException">Thrown if row or column index is out of range.</exception>
        /// <exception cref="InvalidOperationException">Thrown if database operations fail.</exception>
        /// <exception cref="Exception">Propagates unhandled exceptions from the API.</exception>
        public static void EmbedPrimitivesToTableCell(
            this McTable table, 
            int rowIndex, 
            int columnIndex, 
            List<EntityGeometry> entities)
        {
            if (table == null)
                throw new ArgumentNullException(nameof(table));
            if (entities == null)
                throw new ArgumentNullException(nameof(entities));

            // Validate row index
            if (rowIndex < 0 || rowIndex >= table.Rows.Count)
                throw new ArgumentOutOfRangeException(
                    nameof(rowIndex), 
                    "Row index must be within table's row count.");

            // Validate column index
            if (columnIndex < 0 || columnIndex >= table.Columns.Count)
                throw new ArgumentOutOfRangeException(
                    nameof(columnIndex), 
                    "Column index must be within table's column count.");

            Database db = table.Database;
            if (db == null)
                throw new InvalidOperationException("Table's database reference is null.");

            using (Transaction transaction = db.TransactionManager.StartTransaction())
            {
                try
                {
                    // Access target cell
                    McRow row = table.Rows[rowIndex];
                    McCell cell = row.Cells[columnIndex];

                    // Embed each entity into the cell
                    foreach (EntityGeometry entity in entities)
                    {
                        if (entity == null) continue;
                        cell.Geometry.AppendEntity(entity);
                    }

                    transaction.Commit();
                }
                catch
                {
                    transaction.Abort();
                    throw;
                }
            }
        }
    }
}
'''

