import { planets } from './solar_system_data.json';

const canvas = document.getElementById('solarSystem');
const ctx = canvas.getContext('2d');
let animationId;

// Responsive canvas setup
function resizeCanvas() {
    canvas.width = window.innerWidth * window.devicePixelRatio;
    canvas.height = window.innerHeight * window.devicePixelRatio;
    canvas.style.width = window.innerWidth + 'px';
    canvas.style.height = window.innerHeight + 'px';
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

// Simulation parameters
const CENTER = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
let time = 0;
const SCALE = 1e-9; // Scale from km to pixels

function drawPlanet(planet, position) {
    // Draw orbit
    ctx.beginPath();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.arc(CENTER.x, CENTER.y, planet.orbital_radius * SCALE, 0, Math.PI * 2);
    ctx.stroke();

    // Draw planet
    ctx.beginPath();
    ctx.fillStyle = planet.color;
    ctx.arc(position.x, position.y, Math.max(2, Math.log(planet.radius)), 0, Math.PI * 2);
    ctx.fill();
}

function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Sun
    ctx.beginPath();
    ctx.fillStyle = '#FFFF00';
    ctx.arc(CENTER.x, CENTER.y, 5, 0, Math.PI * 2);
    ctx.fill();

    // Update and draw planets
    planets.forEach(planet => {
        // Calculate position using elliptical orbit model
        // (In a real implementation, we would use the actual position data from the backend)
        const days_since_epoch = (Date.now() - new Date(2023, 1, 1)) / (24 * 3600);
        const angle = (days_since_epoch / planet.period) * 2 * Math.PI;
        const x = CENTER.x + planet.position.x * SCALE;
        const y = CENTER.y + planet.position.y * SCALE;

        drawPlanet(planet, { x, y });
    });

    time += 0.1;
    animationId = requestAnimationFrame(animate);
}

// Start animation
animate();

// Handle accessibility and device input
window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        cancelAnimationFrame(animationId);
        ctx.fillStyle = 'white';
        ctx.fillText('Simulation paused. Press R to resume.', 10, 20);
    }
    if (e.key === 'r' || e.key === 'R') {
        animate();
    }
});
